// The real Ortex brand mark, taken verbatim from the other apps:
//   wordmark  <- Ortex.Admin/public/logo.svg      (the one printed on documents)
//   symbol    <- Ortex.Web/public/img/logo-symbol.svg
//
// Kept as SVG XML rather than a PNG so it stays sharp at every density and can
// be recoloured — the loader and lock screen need a white mark on the brand
// blue, and the sign-in screen needs it in full colour.
//
// Note the brand blue is #2F50E4, which is NOT palette.primary (#2567E8). The
// logo keeps its own colour on purpose; it is a fixed asset, not a themed one.

export const ORTEX_BLUE = "#2F50E4"

