/**
 * Recolour every fill in a mark — used to paint it white on the brand-blue
 * splash. Leaves fill="none" alone, which is the SVG's own "do not paint".
 */
export function tintSvg(svg: string, color: string): string {
  return svg.replace(/fill="(?!none")[^"]*"/g, `fill="${color}"`)
}

/**
 * The wordmark as a data URI, for the printed quotation. The document is HTML
 * handed to expo-print, and a remote <img> may not have loaded by the time the
 * PDF is snapshotted — so the mark is inlined rather than fetched.
 */
export const ORTEX_WORDMARK_DATA_URI =
  "data:image/svg+xml;base64,"

